#include <iostream>
#include <string>
#include <typeinfo>
using namespace std;

class Cat {
public:
    string name;
    Cat(const string& n) : name(n) {}
    virtual ~Cat() {}
};

class OrangeCat : public Cat {
public:
    OrangeCat(const string& n) : Cat(n) {}
};

int main() {
    OrangeCat o("{who}");
    Cat* p = &o;
    cout << (typeid(*p) == typeid(OrangeCat) ? "是橘猫图纸" : "不是橘猫图纸") << endl;
    return 0;
}
